## Code Example
```javascript
function computeEarliestFinish(n, durations, edges) {
  const adj = Array.from({ length: n }, () => []);
  const indeg = Array(n).fill(0);
  for (const [u, v] of edges) { adj[u].push(v); indeg[v]++; }
  const est = durations.slice();
  const q = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) q.push(i);
  let processed = 0;
  while (q.length) {
    const u = q.shift();
    processed++;
    for (const v of adj[u]) {
      if (est[v] < est[u] + durations[v]) est[v] = est[u] + durations[v];
      if (--indeg[v] === 0) q.push(v);
    }
  }
  if (processed !== n) throw new Error('Cycle detected');
  return { est, total: Math.max(...est) };
}
```

